// Package api implements the owner API defined in
// packages/api-spec/openapi.yaml. api.gen.go and unimplemented.gen.go are
// generated by `pnpm codegen`; never edit them by hand. Handlers translate
// HTTP to domain calls and map domain sentinel errors to status codes here,
// and only here.
package api

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
)

// ErrNotImplemented is returned by operations that are in the contract but
// not built yet. The handler answers it with 501 not_implemented.
var ErrNotImplemented = errors.New("operation not implemented")

// Server implements StrictServerInterface. Operations it does not declare
// itself fall through to the embedded Unimplemented stub.
type Server struct {
	Unimplemented

	// Version is reported by GET /api/v0/health.
	Version string
}

var _ StrictServerInterface = (*Server)(nil)

// Handler returns the API routes, mounted under /api/ on the dashboard host.
func (s *Server) Handler() http.Handler {
	return newHandler(s)
}

func newHandler(ssi StrictServerInterface) http.Handler {
	strict := NewStrictHandlerWithOptions(ssi, nil, StrictHTTPServerOptions{
		RequestErrorHandlerFunc:  badRequest,
		ResponseErrorHandlerFunc: responseError,
	})
	return HandlerWithOptions(strict, StdHTTPServerOptions{ErrorHandlerFunc: badRequest})
}

// GetHealth reports that the API is serving requests.
func (s *Server) GetHealth(context.Context, GetHealthRequestObject) (GetHealthResponseObject, error) {
	return GetHealth200JSONResponse{Status: HealthStatusOk, Version: s.Version}, nil
}

// badRequest answers a request whose parameters or body could not be decoded.
func badRequest(w http.ResponseWriter, _ *http.Request, _ error) {
	writeError(w, http.StatusBadRequest, "invalid_request", "The request is malformed.")
}

// responseError answers an error returned by an operation.
func responseError(w http.ResponseWriter, _ *http.Request, err error) {
	if errors.Is(err, ErrNotImplemented) {
		writeError(w, http.StatusNotImplemented, "not_implemented", "This operation is not implemented yet.")
		return
	}
	writeError(w, http.StatusInternalServerError, "internal", "Internal server error.")
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(Error{Code: code, Message: message})
}
